<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'; import { api } from '../api'; import type { PageData } from '../types'; import PageHeader from '../components/PageHeader.vue'; import { RefreshCw, Search } from 'lucide-vue-next';
const tab=ref('audit'),q=ref(''),rows=ref<any[]>([]),total=ref(0),loading=ref(false),error=ref('');let timer:number|undefined;async function load(){loading.value=true;error.value='';try{const d=await api<PageData<any>>(`/system/logs/${tab.value}?page=1&pageSize=50&q=${encodeURIComponent(q.value)}`);rows.value=d.items;total.value=d.total;}catch(e){error.value=e instanceof Error?e.message:'加载失败';}finally{loading.value=false;}}watch([tab,q],()=>{clearTimeout(timer);timer=window.setTimeout(load,180)});onMounted(load);const format=(v:string)=>new Date(v).toLocaleString('zh-CN');
</script>
<template><PageHeader title="日志审计" description="认证结果与重要业务操作全程留痕。" :count="total"><el-button :icon="RefreshCw" @click="load">刷新</el-button></PageHeader><el-tabs v-model="tab"><el-tab-pane label="操作日志" name="audit"/><el-tab-pane label="登录日志" name="login"/></el-tabs><div class="table-toolbar"><el-input v-model="q" :prefix-icon="Search" clearable :placeholder="tab==='audit'?'搜索模块、对象或操作':'搜索登录账号'"/></div><div v-if="error" class="error-state"><span>{{error}}</span><el-button @click="load">重试</el-button></div><el-table v-else v-loading="loading" :data="rows" empty-text="暂无日志"><template v-if="tab==='audit'"><el-table-column label="时间" width="180"><template #default="{row}">{{format(row.createdAt)}}</template></el-table-column><el-table-column label="模块" prop="module"/><el-table-column label="对象" min-width="150"><template #default="{row}">{{row.objectType}} · {{row.objectId??'—'}}</template></el-table-column><el-table-column label="操作" prop="action"/><el-table-column label="角色" prop="roleNames" min-width="160"/><el-table-column label="结果" width="90"><template #default="{row}"><el-tag type="success" effect="plain">{{row.result}}</el-tag></template></el-table-column></template><template v-else><el-table-column label="时间" width="180"><template #default="{row}">{{format(row.createdAt)}}</template></el-table-column><el-table-column label="账号" prop="username"/><el-table-column label="结果" width="100"><template #default="{row}"><el-tag :type="row.success?'success':'danger'" effect="plain">{{row.success?'成功':'失败'}}</el-tag></template></el-table-column><el-table-column label="说明" prop="message" min-width="220"/><el-table-column label="IP" prop="ip"/></template></el-table></template>
